Behaviors.setup[Unit] { ctx =>
  val pool = Routers.pool(poolSize = 4) {
    Behaviors.supervise(Worker()).onFailure[Exception](SupervisorStrategy.restart)
  }
  val router = ctx.spawn(pool, "orders-pool")
  router ! Worker.DoLog("order-1")

  val withBroadcast = pool.withBroadcastPredicate(_.isInstanceOf[Audit])   // rule change
  ctx.spawn(withBroadcast, "audit-pool") ! Audit("order-1")
}

