type Rule = PartialFunction[Message, Destination]
private val live = new AtomicReference[Rule](Rules.initial)

def route(m: Message): Destination =
  live.get().applyOrElse(m, (_: Message) => DeadLetter)   // snapshot per message

def publish(rules: Seq[Rule]): Unit =
  live.set(rules.reduce(_ orElse _))                      // control channel
